package sqlancer.cloudberry.gen;

import java.util.ArrayList;
import java.util.List;

import sqlancer.cloudberry.CloudberryBugs;
import sqlancer.common.query.ExpectedErrors;

/**
 * Expected (i.e. non-fatal) errors that Apache Cloudberry may return for statements generated by the reused PostgreSQL
 * generators. These stem from Cloudberry's MPP restrictions (distribution keys, replicated tables, append-optimized /
 * column-oriented / PAX storage) that vanilla PostgreSQL does not have. The list is expected to grow as smoke runs
 * surface new benign errors.
 */
public final class CloudberryCommon {

    private CloudberryCommon() {
    }

    public static List<String> getCloudberryErrors() {
        List<String> errors = new ArrayList<>();

        // Distribution key vs. unique/primary-key constraints. The distribution key must be a subset of every
        // UNIQUE / PRIMARY KEY constraint (verified on the live cluster).
        errors.add("PRIMARY KEY and DISTRIBUTED BY definitions are incompatible");
        errors.add("UNIQUE and DISTRIBUTED BY definitions are incompatible");
        errors.add("must be a subset of the PRIMARY KEY");
        errors.add("must be a subset of the UNIQUE");
        // "ALTER TABLE t1 SET DISTRIBUTED BY (c0)" on a table whose PRIMARY KEY
        // doesn't cover c0 raises this wording, not the "must be a subset of the PRIMARY KEY" one above. It went
        // uncaught, killed the thread mid-cycle before it could DROP its database, and the next JVM's fresh
        // createDatabase() (no defensive DROP first) then collided with that orphaned leftover -- one root cause,
        // a test failure unrelated to the oracle that happened to be running.
        errors.add("distribution policy is not compatible with the table's PRIMARY KEY");
        errors.add("UNIQUE or PRIMARY KEY definitions are incompatible with each other");
        errors.add("Cannot parallelize an UPDATE statement that updates the distribution columns");
        errors.add("must contain all columns in the table's distribution key");
        errors.add("cannot alter type of a column used in a distribution policy");
        errors.add("distribution key");
        // A table with a unique index cannot be distributed RANDOMLY or REPLICATED.
        errors.add("because relation has unique index");

        // Distribution key type restrictions: a hash-distribution key needs a default hash operator class.
        errors.add("is not a hash distributable data type");
        errors.add("type does not have a default operator class");
        errors.add("no default operator class");
        errors.add("cannot use column of type");

        // Replicated / randomly distributed table restrictions.
        errors.add("cannot set the distribution policy of a partitioned table");
        // Verified on the live cluster: a partitioned table's distribution policy can only be BY/RANDOMLY, never
        // REPLICATED, and a leaf partition can never have its own policy at all (it always follows the root).
        errors.add("can't set the distribution policy of");
        errors.add("relation is not distributed");
        errors.add("gp_distribution_policy");

        // The generic (inherited) INSERT/UPDATE generators do not know that a leaf partition created by
        // createLeafPartitions() is constrained: a HASH leaf only accepts rows hashing to its own remainder, so a
        // directly-targeted INSERT/UPDATE frequently violates it. Found live: "INSERT INTO t0_h1(c0) VALUES(-1)"
        // crashed the fuzzer with this exact, otherwise-uncaught error.
        errors.add("violates partition constraint");

        // Append-optimized / column-oriented / PAX storage restrictions.
        errors.add("append-only");
        errors.add("appendonly");
        errors.add("appendoptimized");
        errors.add("column-oriented");
        errors.add("does not support");
        errors.add("is not supported on appendoptimized relations");
        errors.add("unsupported operation on an appendoptimized relation");
        errors.add("is not supported for appendoptimized relations");
        errors.add("feature not supported on appendoptimized relations");
        errors.add("cannot reindex append-only columnar table");
        errors.add("cannot reindex PAX table");
        errors.add("there is no previously clustered index");
        errors.add("is missing support function");
        // Speculative insertion (ON CONFLICT DO NOTHING/UPDATE) is unimplemented for PAX tables.
        errors.add("not implemented yet on pax relations");
        errors.add("and DISTRIBUTED RANDOMLY are incompatible");

        // Cloudberry does not implement unlogged sequences, so any UNLOGGED table carrying a sequence-backed
        // column -- serial / bigserial, or GENERATED { ALWAYS | BY DEFAULT } AS IDENTITY -- is rejected outright,
        // while the same table without such a column (and the same column in a logged table) is accepted. The
        // inherited PostgreSQL table generator combines UNLOGGED and serial/identity freely, since vanilla
        // Postgres creates an unlogged sequence to match. Verified on the live cluster: "CREATE UNLOGGED SEQUENCE
        // s0" fails with this same message on its own.
        errors.add("unlogged sequences are not supported");

        // Inheritance restrictions specific to Cloudberry's MPP planner.
        errors.add("can't split update for inherit table");
        // An UPDATE/DELETE whose result relations span an inheritance hierarchy is rejected when its members do not
        // all share one distribution policy *type* (createplan.c, ERRCODE_FEATURE_NOT_SUPPORTED: Cloudberry cannot
        // modify tables on the segments and on the entry DB in one process). The wording names the entry-DB case,
        // but the check compares GpPolicyType, so it also fires for combinations that involve no entry-only table
        // at all -- the live occurrence was a DISTRIBUTED BY parent with a DISTRIBUTED REPLICATED child, reached
        // because the inherited generator assigns each table its own policy with no regard for its parent's.
        errors.add("ModifyTable mixes distributed and entry-only tables");

        // Verified on the live cluster: altering the type of a column carrying a PRIMARY KEY/UNIQUE constraint is
        // rejected outright ("Hint: DROP the constraint first, and recreate it after the ALTER"), unlike vanilla
        // Postgres, which allows it via a table rewrite.
        errors.add("cannot alter column with primary key or unique constraint");

        // Verified on the live cluster: Cloudberry's grammar reserves the bare word "partition" more strictly than
        // vanilla Postgres, which accepts it unquoted as a GUC value (e.g. "SET constraint_exclusion = partition").
        // Quoting it ("SET constraint_exclusion = 'partition'") works fine; only the bare, unquoted token fails.
        errors.add("syntax error at or near \"partition\"");

        // Standard PostgreSQL inheritance semantics, not Cloudberry-specific: "ALTER TABLE ONLY parent ... SET NOT
        // NULL" is only legal when every child already independently satisfies the constraint. Unreachable before
        // createLeafPartitions() existed (every partitioned table was leafless), now reachable via e.g. the
        // "<table>_default" leaf partition.
        errors.add("constraint must be added to child tables too");
        // Likewise standard PostgreSQL partitioning semantics (tablecmds.c), and likewise only reachable once a
        // partitioned table actually has leaf partitions: "ALTER TABLE ONLY parent DROP CONSTRAINT" is refused,
        // because the partitions would be left carrying a constraint their parent no longer has.
        errors.add("cannot remove constraint from only the partitioned table when partitions exist");

        // See CloudberryBugs for details on each of these known, still-open target-DB bugs. Each is gated behind
        // a public static flag there (mirroring TiDBBugs) so the workaround is easy to find and delete once the
        // underlying bug is fixed, rather than living here as an unexplained flat string.
        if (CloudberryBugs.bugFullMergeJoinUnexpectedGangSize) {
            errors.add("unexpected gang size");
        }

        // One bug with two faces: depending on the predicate, the bad Index Cond is caught either by
        // nodeIndexscan.c's own check or by nbtree's, so both messages have to be suppressed together.
        if (CloudberryBugs.bugIndexCondOnIncludedColumn) {
            errors.add("bogus index qualification");
            errors.add("btree index keys must be ordered by attribute");
        }

        if (CloudberryBugs.bugAocoReindexConcurrentlyNotImplemented) {
            errors.add("not implemented yet (aocsam_handler.c");
        }

        // Only the precise, unambiguous assertion signature is suppressed here -- NOT its generic connection-loss
        // fallout ("connection has been closed", "I/O error...", "recovery mode", etc.). Those messages are left
        // unfiltered on purpose (decision reversed 2026-09-16): a generic connection-loss error could be fallout
        // from this exact bug, but it could just as easily be a different, not-yet-diagnosed crash, and blanket-
        // suppressing it risks hiding a new bug behind a known one. This string, by contrast, is a fingerprint
        // that can only ever be this one bug, so it's safe to suppress with full confidence. A fix already has an
        // MR open against Cloudberry; once merged and this environment is rebuilt against it, flip the flag below
        // to false and this line becomes dead code to delete.
        if (CloudberryBugs.bugOrSelectivityNotClampedAssert) {
            errors.add("pselec >= 0.0 && pselec <= 1.0");
        }

        // Exclusion constraints and foreign keys on distributed tables.
        errors.add("exclusion constraints");
        errors.add("EXCLUDE");
        // An EXCLUDE constraint must cover the distribution key, and the live
        // wording is singular ("exclusion constraint is not compatible with the table's distribution policy",
        // DETAIL: "Distribution key column \"c1\" is not included in the constraint."). Neither the plural
        // "exclusion constraints" entry above nor the uppercase "EXCLUDE" one matches that message, so it went
        // uncaught and killed the thread at CREATE TABLE.
        errors.add("exclusion constraint is not compatible with the table's distribution policy");
        errors.add("foreign key constraint");

        // Several storage WITH-options (e.g. parallel_workers) are generated from a range wider than what the
        // server actually accepts (bounded by GUCs like max_worker_processes), so out-of-range values are routine.
        // Not Cloudberry-specific -- vanilla Postgres would reject these the same way -- but added here rather than
        // in the shared postgres/ generator so this stays a Cloudberry-only change.
        errors.add("out of bounds for option");

        // Generic MPP planner / executor restrictions and interconnect timeouts.
        errors.add("not supported in Apache Cloudberry");
        errors.add("not supported by Apache Cloudberry");
        errors.add("This query is not currently supported by GPDB");
        errors.add("could not devise a query plan");
        // Live wording is "could not devise a plan (cdbpath.c:...)" -- no "query" -- so the entry above never
        // actually matches; keep both since it's unclear which build/error-path produces which variant.
        errors.add("could not devise a plan");
        errors.add("function cannot execute on a QE slice");
        errors.add("cannot execute on a QE slice");
        errors.add("canceling statement due to statement timeout");

        return errors;
    }

    public static void addCloudberryErrors(ExpectedErrors errors) {
        errors.addAll(getCloudberryErrors());
    }
}
